const errors = {}

/** Three steps, with a wait between the second and the third for a nudge or a timer. */
export const Pipeline = Roadbook.make<PipelineDef>(ir, "Pipeline", errors)

// ---- machine: Parent ----

export const Push = Schema.TaggedStruct("Push", { by: Schema.Int })
export type Push = typeof Push.Type

export interface ParentDef extends Roadbook.MachineDef {
  readonly name: "Parent"
  readonly input: { readonly id: string }
  readonly output: number
  readonly error: never
  readonly event: Push
  readonly emits: never
  readonly state: "Parent" | "Parent.Running" | "Parent.Fallback" | "Parent.Done" | "Parent.GaveUp"
  readonly fns: { readonly deadline: { readonly args: {}; readonly returns: Duration.Duration } }
  readonly actions: {}
  readonly tasks: {
    readonly step: {
      readonly args: { readonly n: number }
      readonly success: number
      readonly error: never
    }
  }
  readonly machines: {
    readonly Pipeline: {
      readonly args: { readonly id: string }
      readonly success: number
      readonly error: never
    }
  }
}

/**
 * Runs a Pipeline as a child and passes nudges on to it. Past its deadline it cancels the
 * Pipeline and does a fourth step instead.
 */
export const Parent = Roadbook.make<ParentDef>(ir, "Parent", errors)

// ---- machine: Counter ----

export const Add = Schema.TaggedStruct("Add", { by: Schema.Int })
export type Add = typeof Add.Type

export const Close = Schema.TaggedStruct("Close", {})
export type Close = typeof Close.Type

export const Total = Schema.TaggedStruct("Total", { n: Schema.Int })
export type Total = typeof Total.Type

export interface CounterDef extends Roadbook.MachineDef {
  readonly name: "Counter"
  readonly input: {}
  readonly output: void
  readonly error: never
  readonly event: Add | Close
  readonly emits: Total
  readonly state: "Counter" | "Counter.Counting" | "Counter.Closed"
  readonly fns: {}
  readonly actions: {}
  readonly tasks: {}
  readonly machines: {}
}

/** Adds what it is sent, and emits each new total to the runs holding a `ref` to it. */
export const Counter = Roadbook.make<CounterDef>(ir, "Counter", errors)

// ---- machine: Adder ----

export interface AdderDef extends Roadbook.MachineDef {
  readonly name: "Adder"
  readonly input: { readonly counter: Roadbook.Handle<CounterDef>; readonly goal: number }
  readonly output: number
  readonly error: never
  readonly event: never
  readonly emits: never
  readonly state: "Adder" | "Adder.Working" | "Adder.Waiting" | "Adder.Reached"
  readonly fns: {}
  readonly actions: {}
  readonly tasks: {
    readonly step: {
      readonly args: { readonly n: number }
      readonly success: number
      readonly error: never
    }
  }
  readonly machines: {}
}

/** Works out an amount, sends it to a Counter, and ends once the Counter's total reaches `goal`. */
export const Adder = Roadbook.make<AdderDef>(ir, "Adder", errors)

// ---- machine: Watcher ----

export interface WatcherDef extends Roadbook.MachineDef {
  readonly name: "Watcher"
  readonly input: { readonly counter: Roadbook.Handle<CounterDef> }
  readonly output: number
  readonly error: never
  readonly event: never
  readonly emits: never
  readonly state: "Watcher" | "Watcher.Working" | "Watcher.Done"
  readonly fns: {}
  readonly actions: {}
  readonly tasks: {
    readonly step: {
      readonly args: { readonly n: number }
      readonly success: number
      readonly error: never
    }
  }
  readonly machines: {}
}

/**
 * Counts the ends of its Counter it takes, while it works: once, however the processes
 * running it crash.
 */
export const Watcher = Roadbook.make<WatcherDef>(ir, "Watcher", errors)

